style.css:
@-moz-document domain("example.com") {
/* General background and text colors */
    body {
        background-color: #1A1F3B !important;  /* Navy Blue */
        color: #E0E0E0 !important;  /* Light Grey */
    }

    /* Headers */
    h1, h2, h3, h4, h5, h6 {
        color: #6B5ED6 !important;  /* Purple-Blue */
    }

    /* Links */
    a {
        color: #FF1493 !important;  /* Hot Pink */
    }
    a:hover {
        color: #6B5ED6 !important;  /* Purple-Blue */
    }

    /* Buttons */
    button {
        background-color: #0033A0 !important;  /* Deep Blue */
        color: #E0E0E0 !important;  /* Light Grey */
        border: 2px solid #6B5ED6 !important;  /* Purple-Blue */
        padding: 10px 15px !important;
        border-radius: 5px !important;
        font-weight: bold !important;
    }
    button:hover {
        background-color: #6B5ED6 !important;
        color: #1A1F3B !important;
    }

    /* Input fields */
    input, textarea {
        background-color: #2C2F45 !important;  /* Dark Grey-Blue */
        color: #E0E0E0 !important;
        border: 1px solid #6B5ED6 !important;
    }

    /* Navigation bar */
    nav {
        background-color: #0033A0 !important;
        border-bottom: 3px solid #FF1493 !important;
    }

    /* Footer */
    footer {
        background-color: #1A1F3B !important;
        color: #E0E0E0 !important;
        border-top: 2px solid #6B5ED6 !important;
    }
}
